    walls={(i,j) for i in range(H) for j in range(W) if g[i][j]==3}
    seen=[[False]*W for _ in range(H)]
    q=deque()
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and (i in(0,H-1) or j in(0,W-1)): seen[i][j]=True; q.append((i,j))
    while q:
        a,b=q.popleft()
        for di in(-1,0,1):
            for dj in(-1,0,1):
                x,y=a+di,b+dj
                if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==0:
                    seen[x][y]=True; q.append((x,y))
    inter=[(i,j) for i in range(H) for j in range(W) if not seen[i][j]]
    maxd=max(min(max(abs(i-a),abs(j-b)) for a,b in walls) for i,j in inter)
    res=[r[:] for r in g]
    for i,j in inter:
        dd=min(max(abs(i-a),abs(j-b)) for a,b in walls)
        res[i][j]=3 if dd==maxd else (4 if dd%2==1 else 2)
    return res
